def can_jump(nums):
    farthest = 0                      # the highest index we know how to reach; every index before it is reachable too
    for i, jump in enumerate(nums):
        if i > farthest:
            return False              # index i cannot be reached, and neither can anything after it
        farthest = max(farthest, i + jump)
    return True
